endpoints.responseShape:
// JSON array (possibly empty), each element = a TimeSlot plus clinic name plus isBooked:
[
  {
    "id": "uuid",
    "clinicId": "uuid",
    "physicianId": "uuid",              // PhysicianProfile.id, NOT the userId that was queried
    "dayOfWeek": 0,                      // int 0=Sunday .. 6=Saturday
    "startTime": "09:00",                // string
    "endTime": "09:30",                  // string
    "slotDuration": 30,                  // int minutes
    "isActive": true,                    // always true (where-filtered), still emitted
    "createdAt": "ISO string",
    "clinic": { "name": "string" },      // name ONLY
    "isBooked": false                    // computed, appended last by the spread
  }
]

// The requested date is NOT echoed anywhere in the response - the client must remember it.
// Key order: TimeSlot scalars in schema order, then clinic, then isBooked.

// ---------- Branch A: fewer than 5 appointments in the window (EARLY RETURN, 200) ----------
{
  "stats": null,
  "insights": [],
  "message": "Not enough appointment data for analysis. Need at least 5 appointments in the last 90 days."
}
// NOTE: "aiProvider" is ABSENT in this branch, and "message" is ABSENT in the normal branch.

// ---------- Branch B: normal (200) ----------
{
  "stats": {
    "totalAppointments": 42,                 // int
    "completed": 30,                         // int
    "noShows": 5,                            // int  (key is plural, unlike the *Rate keys)
    "cancelled": 4,                          // int  (British spelling, two L's)
    "noShowRate": 0.119,                     // number, 3 decimals, 0..1 FRACTION not percent
    "cancelRate": 0.095,                     // number, 3 decimals  (key is cancelRate, not cancelledRate)
    "completionRate": 0.714,                 // number, 3 decimals
    "avgVisitDurationMin": 18,               // int OR null when no usable completed visits
    "avgSlotDuration": 30,                   // int, defaults to 30 when no active slots
    "peakHour": "14:00",                     // STRING built as `${hourKey}:00`, defaults to "09:00"
    "busiestDay": "Monday",                  // English day name, or the literal "N/A"
    "avgDailyPatients": 3.5,                 // number, 1 decimal
    "slotUtilization": 0.404,                // number, 3 decimals, CAPPED at 1
    "dayStats": [                            // array, sorted by total DESC; only days that occur
      {
        "day": "Monday",                     // dayNames[dayIndex], English, Sunday-first
        "dayIndex": 1,                       // int 0..6, 0=Sunday
        "total": 12,                         // int
        "noShowRate": 0.083,                 // number, 3 decimals
        "cancelRate": 0.0                    // number, 3 decimals
      }
    ],
    "hourDistribution": [                    // array, sorted by hour string localeCompare ASC
      { "hour": "09:00", "count": 7 }         // hour = `${startTime.split(':')[0]}:00`
    ],
    "typeBreakdown": {                        // OBJECT map, only types present; keys unordered-ish
      "IN_PERSON": 30,
      "WALK_IN": 12
    },
    "totalActiveSlotsPerWeek": 13,           // int = activeSlots.length
    "analyzedDays": 12                       // int = distinct calendar days with appointments
  },
  "insights": [                               // array, 0..6 items; [] on ANY AI or parse failure
    {
      "type": "NO_SHOW",                      // one of NO_SHOW|SLOT_DURATION|PEAK_HOURS|UTILIZATION|CANCELLATION|THROUGHPUT (else coerced to "THROUGHPUT")
      "title": "string",                      // truncated to 120 chars
      "description": "string",                // truncated to 500 chars
      "impact": "HIGH"                        // HIGH|MODERATE|LOW (else coerced to "MODERATE")
    }
  ],
  "aiProvider": "openai"                      // "openai" | "gemini" | "micromind" | null
}

// stats key order is exactly as listed above (object-literal order at L1487-L1505).
